"""
    Check and fix detector name strings.

    Parameters
    ----------
    detector : `str`
        The detector name to check.
    """
def _parse_detector(detector: Any) -> object {
    oklist = ['n0', 'n1', 'n2', 'n3', 'n4', 'n5', 'n6', 'n7', 'n8', 'n9', 'n10', 'n11'];
    altlist = [str(i) for i in range(12)];
    if (detector in oklist) {
        return detector;
    } elif (detector in altlist) {
        return ('n' + detector);
    } else {
        raise ValueError('Detector string could not be interpreted');
    }
}

"""
        get list obj first not-null object
            >>> first_not_null(None, 'a', 'b')
        return 'a'
    """
def first_not_null(*args: Any) -> object {
    if (args is not None) {
        for arg in args {
            if (arg is not None) {
                return arg;
            }
        }
    }
    return None;
}

